/* Visual Lab Word Trails levels 12–30. Clean crossword spacing: no unrelated touching tiles; Scripture facts tied to NWT on JW.org. Original 11 levels unchanged. */
window.BUWTAdditionalLevels=Object.freeze([{"rack":"JESUSE","size":6,"title":"The Promised Son","scene":"40_matthew.webp","spark":"SUE","clue":"Jesus described someone trying to take you to court over an inner garment. What's the everyday verb for that legal action?","reference":"Matthew 5:40","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/5/","insight":"Jesus said that if someone tried to take your inner garment in court, you could even offer your outer garment. His example invites us to think beyond simply winning a dispute.","words":[["JESUS",2,0,"across"],["JESSE",4,0,"across"],["USES",1,2,"down"],["SUES",2,4,"down"]],"bibleBoard":[{"word":"JESUS","clue":"The name the angel directed Joseph to give Mary's son","reference":"Matthew 1:21","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/1/","insight":"Joseph was told to name Mary's son Jesus because he would save his people from their sins."},{"word":"JESSE","clue":"David's father, who lived in Bethlehem","reference":"1 Samuel 16:1","url":"https://www.jw.org/en/library/bible/nwt/books/1-samuel/16/","insight":"Jehovah sent Samuel to Jesse in Bethlehem to anoint a future king."}],"bonus":"USE SEES","extraSparks":[{"word":"SEE","clue":"Jesus told a man who'd been blind since birth to wash in Siloam. What could the man finally do afterward?","reference":"John 9:7","url":"https://www.jw.org/en/library/bible/nwt/books/john/9/","insight":"The man had been blind from birth. After following Jesus' instruction, he returned able to see! His neighbors were so surprised that some wondered whether he was even the same man."}]},{"rack":"ESTHER","size":6,"title":"Courage in Persia","scene":"17_esther.webp","spark":"REST","clue":"Jesus invited people weighed down by heavy burdens to come to him for refreshment. What's a simple word for that kind of relief?","reference":"Matthew 11:28-30","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/11/","insight":"Jesus wasn't promising to make every problem disappear overnight. He invited burdened people to learn from his mild, humble example and find refreshment. Isn't that a comforting kind of rest when life feels heavy?","words":[["ESTHER",2,0,"across"],["SETH",2,1,"down"],["TREE",4,1,"across"],["HERE",1,4,"down"]],"bibleBoard":[{"word":"ESTHER","clue":"The young Jewish woman who became queen in Persia","reference":"Esther 2:7, 11, 17","url":"https://www.jw.org/en/library/bible/nwt/books/esther/2/","insight":"Esther lost both parents, and her cousin Mordecai raised her as his own daughter. Even after she was taken into the king's household, he kept checking on her welfare. Later, she became queen."},{"word":"SETH","clue":"The son born to Adam and Eve after Abel's death","reference":"Genesis 4:25","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/4/","insight":"Eve named her son Seth after Abel was killed."}],"bonus":"THE HER SHE SET THESE SHEET ETHER","extraSparks":[{"word":"THREE","clue":"How many faithful Hebrews were thrown into the fiery furnace?","reference":"Daniel 3:16-23","url":"https://www.jw.org/en/library/bible/nwt/books/daniel/3/","insight":"Shadrach, Meshach, and Abednego refused to worship the golden image, even under threat of death. Their faithfulness wasn't conditional on knowing whether Jehovah would rescue them."}]},{"rack":"DANIEL","size":6,"title":"Faith in Babylon","scene":"27_daniel.webp","spark":"ELI","clue":"Which elderly priest died after hearing that the Ark of the true God had been captured?","reference":"1 Samuel 4:13-18","url":"https://www.jw.org/en/library/bible/nwt/books/1-samuel/4/","insight":"Eli was 98 and could no longer see. A messenger brought news of Israel's defeat, the death of his sons, and the capture of the Ark. When he heard that the Ark had been taken, Eli fell backward and died. What a sad ending to his long life.","words":[["DANIEL",2,0,"across"],["DAN",4,3,"across"],["IDEAL",0,1,"across"],["LINE",2,5,"down"],["DEAL",2,0,"down"],["DINE",0,2,"down"]],"bibleBoard":[{"word":"DANIEL","clue":"Prophet who was thrown into a lions' pit","reference":"Daniel 6:16","url":"https://www.jw.org/en/library/bible/nwt/books/daniel/6/","insight":"Daniel's faithfulness continued even when he was placed in a lions' pit."},{"word":"DAN","clue":"Jacob's son whose name Rachel chose","reference":"Genesis 30:6","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/30/","insight":"Although Bilhah gave birth to the boy, Rachel named him Dan. Rachel said that God had acted as her judge and listened to her voice. There's a personal story behind that short name!"}],"bonus":"NAIL LIE LANE LAND LEAD LEND DIAL LAID LIED IDEA ALIEN","extraSparks":[{"word":"END","clue":"Isaiah said the peace under the promised Prince of Peace would have no what?","reference":"Isaiah 9:6, 7","url":"https://www.jw.org/en/library/bible/nwt/books/isaiah/9/","insight":"Isaiah called the promised ruler the Prince of Peace and said that his peace would have no end. Isn't that a comforting promise?"}]},{"rack":"MOSESH","size":6,"title":"A Shepherd Called","scene":"02_exodus.webp","spark":"HOME","clue":"Jesus freed a man from demon possession. When the man asked to stay with him, where did Jesus tell him to go and share what God had done?","reference":"Luke 8:38, 39","url":"https://www.jw.org/en/library/bible/nwt/books/luke/8/","insight":"The man begged to travel with Jesus. But Jesus told him to go back home and share what God had done for him. So he went through the city telling others what had happened!","words":[["MOSES",2,0,"across"],["SHEM",5,2,"across"],["SOME",2,4,"down"],["HOSE",0,2,"down"],["MESH",2,0,"down"],["SHOE",0,1,"across"]],"bibleBoard":[{"word":"MOSES","clue":"Man sent by Jehovah to lead the Israelites out of Egypt","reference":"Exodus 3:10","url":"https://www.jw.org/en/library/bible/nwt/books/exodus/3/","insight":"Jehovah commissioned Moses to approach Pharaoh and lead Israel out of Egypt."},{"word":"SHEM","clue":"One of Noah's sons who came out of the ark","reference":"Genesis 9:18","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/9/","insight":"Shem was one of Noah's three sons who came out of the ark."}],"bonus":"HOMES MOSS HOSES SHOES HEMS","extraSparks":[{"word":"HEM","clue":"Exodus says gold bells and colorful pomegranates went around what part of Aaron's sleeveless coat?","reference":"Exodus 28:33-35","url":"https://www.jw.org/en/library/bible/nwt/books/exodus/28/","insight":"Can you picture it? Aaron's blue sleeveless coat had gold bells alternating with colorful pomegranates all around its hem. The bells were to be heard when he entered and left the sanctuary. Jehovah gave careful instructions even for details of the priestly clothing!"}]},{"rack":"JONAHIS","size":7,"title":"Prophets and People","scene":"32_jonah.webp","spark":"NOAH","clue":"Righteous man whom Jehovah instructed to build the ark","reference":"Genesis 6:9, 11-14, 22","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/6/","insight":"Noah lived when violence filled the earth. Yet Genesis says he walked with the true God—and he followed Jehovah's instructions for building the ark. His faith showed in what he did.","words":[["JONAH",2,0,"across"],["JOHN",1,6,"down"],["SIN",4,4,"across"],["JOIN",2,0,"down"],["SHIN",0,0,"across"],["IONS",0,2,"down"],["HIS",2,4,"down"]],"bibleBoard":[{"word":"JONAH","clue":"Prophet sent to Nineveh","reference":"Jonah 1:1, 2","url":"https://www.jw.org/en/library/bible/nwt/books/jonah/1/","insight":"Jehovah instructed Jonah to go to the great city of Nineveh."},{"word":"JOHN","clue":"Name given to Elizabeth and Zechariah's son","reference":"Luke 1:13","url":"https://www.jw.org/en/library/bible/nwt/books/luke/1/","insight":"The angel said Elizabeth would have a son and instructed Zechariah to name him John."},{"word":"SIN","clue":"According to Romans 6:23, what pays wages of death?","reference":"Romans 6:23","url":"https://www.jw.org/en/library/bible/nwt/books/romans/6/","insight":"Paul contrasted two very different things: sin pays wages of death, but everlasting life is a gift God gives through Jesus. One is a wage; the other is a gift."}],"bonus":"JOINS ION ASH HAS JOSH","extraSparks":[{"word":"SON","clue":"Jehovah called Jesus his beloved Son","reference":"Mark 1:11","url":"https://www.jw.org/en/library/bible/nwt/books/mark/1/","insight":"At Jesus' baptism, a voice from heaven called him the beloved Son."}]},{"rack":"SARAHM","size":7,"title":"A Family's Journey","scene":"01_genesis.webp","spark":"HAM","clue":"Which of Noah's sons saw his father uncovered and told his brothers?","reference":"Genesis 9:21-23","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/9/","insight":"After Noah became intoxicated and lay uncovered in his tent, Ham saw him and told his brothers. Shem and Japheth took a garment and walked backward to cover their father without looking at him. Notice how differently they handled that uncomfortable situation.","words":[["SARAH",2,1,"across"],["MARAH",0,3,"down"],["HARM",0,0,"across"],["MASH",4,0,"across"],["HAMS",2,5,"down"],["SHAM",2,1,"down"]],"bibleBoard":[{"word":"SARAH","clue":"Abraham's wife, whose name Jehovah changed from Sarai","reference":"Genesis 17:15, 16","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/17/","insight":"Jehovah changed Sarai's name to Sarah while promising that she would have a son. He also said that nations and kings would come from her! Her new name was connected with a remarkable promise."},{"word":"MARAH","clue":"Before reaching Elim, with its 12 springs and 70 palm trees, which campsite had the Israelites just left?","reference":"Numbers 33:1, 2, 8, 9","url":"https://www.jw.org/en/library/bible/nwt/books/numbers/33/","insight":"Moses kept a record of Israel's journey stages at Jehovah's direction. His list places Marah right before Elim, where the Israelites camped near 12 springs and 70 palm trees. Isn't it interesting that the Bible even preserves the order of their stopping places?"}],"bonus":"ASH ARM MARS ARMS HARMS RAMS","extraSparks":[{"word":"RAM","clue":"Which three-year-old male animal did Jehovah tell Abram to bring as part of his covenant account?","reference":"Genesis 15:7-10, 18","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/15/","insight":"When Abram asked about the land Jehovah had promised him, Jehovah told him to bring several animals, including a three-year-old ram. Later in the chapter, Jehovah made a covenant with Abram about that land. That small detail was part of a much bigger promise!"}]},{"rack":"ELIJAH","size":7,"title":"A Prophet Speaks","scene":"11_1_kings.webp","spark":"ELI","clue":"Priest who confronted his sons over their bad conduct at the tabernacle","reference":"1 Samuel 2:22-25","url":"https://www.jw.org/en/library/bible/nwt/books/1-samuel/2/","insight":"Eli heard serious reports about his sons and warned them that their conduct was wrong. But they wouldn't listen. It wasn't an ordinary family disagreement—their actions affected worship at the tabernacle.","words":[["ELIJAH",2,0,"across"],["LEAH",5,3,"across"],["HAIL",0,1,"across"],["JAIL",2,3,"down"],["HALE",0,1,"down"]],"bibleBoard":[{"word":"ELIJAH","clue":"Prophet who spoke boldly to King Ahab","reference":"1 Kings 17:1-6","url":"https://www.jw.org/en/library/bible/nwt/books/1-kings/17/","insight":"Elijah told King Ahab that there would be no rain or dew except by his word. Then Jehovah directed him to a stream, where ravens brought him food. Elijah, too, had to rely on Jehovah during the drought."},{"word":"LEAH","clue":"Rachel's older sister, who became Jacob's wife","reference":"Genesis 29:16, 23","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/29/","insight":"Leah was Laban's older daughter; later, Laban gave her to Jacob in marriage."}],"bonus":"LIE LEI AIL LEA HIE","extraSparks":[{"word":"HEAL","clue":"What did the little Israelite girl believe the prophet in Samaria could do for Naaman?","reference":"2 Kings 5:2, 3, 11-14","url":"https://www.jw.org/en/library/bible/nwt/books/2-kings/5/","insight":"The Israelite girl was a captive in Syria, yet she told Naaman's wife about the prophet in Samaria. Later, when Naaman angrily resisted Elisha's simple instructions, his servants urged him to reconsider. He washed in the Jordan seven times and was healed!"}]},{"rack":"RACHEL","size":7,"title":"Love and Loyalty","scene":"01_genesis.webp","spark":"CARE","clue":"According to 1 Peter 5:7, we can throw our worries on God because of his what?","reference":"1 Peter 5:6, 7","url":"https://www.jw.org/en/library/bible/nwt/books/1-peter/5/","insight":"Peter encouraged Christians to throw all their anxieties on God because he cares for them. He gave that advice right alongside a reminder to be humble. We don't have to pretend our worries aren't real!","words":[["RACHEL",2,0,"across"],["LEAH",2,5,"down"],["REACH",0,1,"across"],["RACE",2,0,"down"],["EACH",0,2,"down"]],"bibleBoard":[{"word":"RACHEL","clue":"Younger daughter of Laban loved by Jacob","reference":"Genesis 29:16-20","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/29/","insight":"Jacob agreed to work seven years for Rachel, whom he loved. Genesis says those years seemed like just a few days to him because of his love for her. What a memorable detail!"},{"word":"LEAH","clue":"Woman Laban gave Jacob in marriage instead of Rachel","reference":"Genesis 29:23-25","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/29/","insight":"Jacob worked seven years to marry Rachel. But at the wedding, Laban gave him Leah, and Jacob discovered the deception the next morning."}],"bonus":"ARCH ACHE HARE REAL LACE CLEAR","extraSparks":[{"word":"HEAR","clue":"Paul asked how people could develop faith if no one preached to them. What do they need a chance to do first?","reference":"Romans 10:14, 17","url":"https://www.jw.org/en/library/bible/nwt/books/romans/10/","insight":"Paul pointed out that people can't put faith in someone they've never heard about. That's why preaching matters: it gives others the chance to hear the good news and decide how they'll respond."}]},{"rack":"SAMSON","size":7,"title":"Strength and Choices","scene":"07_judges.webp","spark":"AMON","clue":"Which king of Judah succeeded Manasseh and ruled for only two years?","reference":"2 Kings 21:18-24","url":"https://www.jw.org/en/library/bible/nwt/books/2-kings/21/","insight":"Amon became king after his father Manasseh, but ruled for just two years. He continued worshipping idols; his son Josiah became king after him.","words":[["SAMSON",3,0,"across"],["AMOS",1,3,"across"],["MOAN",0,5,"down"],["MANS",0,0,"down"],["MASS",0,3,"down"]],"bibleBoard":[{"word":"SAMSON","clue":"Judge whose strength was empowered by Jehovah's spirit","reference":"Judges 15:14, 15","url":"https://www.jw.org/en/library/bible/nwt/books/judges/15/","insight":"When the Philistines came shouting, Jehovah's spirit empowered Samson, and the ropes binding him came apart. He then fought using a donkey's jawbone. The account credits Jehovah's spirit, not just Samson's muscles."},{"word":"AMOS","clue":"Prophet from Tekoa who was among the sheep raisers","reference":"Amos 1:1","url":"https://www.jw.org/en/library/bible/nwt/books/amos/1/","insight":"Amos is introduced as one of the sheep raisers from Tekoa. His prophecy even identifies the kings ruling when he received his message and says it was two years before an earthquake."}],"bonus":"MASON MOANS SONS MOSS SANS","extraSparks":[{"word":"MAN","clue":"Jehovah formed the first one from ground dust","reference":"Genesis 2:7","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/2/","insight":"Genesis says Jehovah formed the man from dust and breathed the breath of life into his nostrils. Then the man became a living person. Notice how the account describes the whole man coming to life."}]},{"rack":"ELISHA","size":7,"title":"Faithful Service","scene":"12_2_kings.webp","spark":"ELI","clue":"Priest who initially mistook Hannah's silent prayer for drunkenness","reference":"1 Samuel 1:12-17","url":"https://www.jw.org/en/library/bible/nwt/books/1-samuel/1/","insight":"Eli saw Hannah's lips moving as she prayed, but he couldn't hear her voice. He wrongly thought she was drunk! When she explained her distress, he told her to go in peace. What a reminder not to jump to conclusions about someone.","words":[["ELISHA",3,0,"across"],["LEAH",0,4,"down"],["AISLE",6,0,"across"],["HAIL",0,1,"across"],["HEAL",0,1,"down"],["SAIL",3,3,"down"]],"bibleBoard":[{"word":"ELISHA","clue":"Prophet who succeeded Elijah","reference":"2 Kings 2:13-15","url":"https://www.jw.org/en/library/bible/nwt/books/2-kings/2/","insight":"After Elijah was taken away, Elisha picked up Elijah's official garment and struck the Jordan. The waters divided, letting him cross! The sons of the prophets at Jericho recognized that Elijah's spirit now rested on Elisha."},{"word":"LEAH","clue":"Jacob's wife who named her third son Levi","reference":"Genesis 29:34","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/29/","insight":"Leah named her third son Levi. She hoped that having borne Jacob three sons would draw her husband closer to her."}],"bonus":"LEASH SHALE LASH SALE LIES ISLE","extraSparks":[{"word":"SEAL","clue":"What was Mordecai to do to the letters written in the king's name using his royal signet ring?","reference":"Esther 8:8-10","url":"https://www.jw.org/en/library/bible/nwt/books/esther/8/","insight":"The king allowed Esther and Mordecai to write letters on behalf of the Jews and seal them with his signet ring. A decree written in the king's name and sealed that way couldn't be revoked. The little seal carried royal authority!"}]},{"rack":"TAMARH","size":7,"title":"Families of Faith","scene":"42_luke.webp","spark":"HAM","clue":"Which son of Noah was the father of Cush, Mizraim, Put, and Canaan?","reference":"Genesis 10:6, 32","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/10/","insight":"Genesis 10 names four of Ham's sons: Cush, Mizraim, Put, and Canaan. The chapter also shows how families and nations spread out after the Flood. Isn't it interesting how a family list can help us trace that history?","words":[["MARTHA",2,0,"across"],["TAMAR",2,3,"down"],["HARM",1,5,"down"],["MATH",2,0,"down"],["TRAM",4,0,"across"],["HART",6,1,"across"]],"bibleBoard":[{"word":"MARTHA","clue":"Woman who welcomed Jesus into her home while her sister Mary listened to him","reference":"Luke 10:38-42","url":"https://www.jw.org/en/library/bible/nwt/books/luke/10/","insight":"Martha warmly welcomed Jesus into her home, but she got distracted by all the work she was doing. Mary chose to sit and listen. Jesus helped Martha see that paying attention to spiritual things mattered more than a perfect visit."},{"word":"TAMAR","clue":"Woman whom Judah arranged to marry his firstborn son, Er","reference":"Genesis 38:6-14","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/38/","insight":"Tamar married Judah's son Er, but he died. Judah later told her to remain a widow until his youngest son grew up. When that time came, however, she still wasn't given to him as a wife. Her story was far more difficult than a family list might suggest."}],"bonus":"MART ARM ART HAT MAT TAR","extraSparks":[{"word":"RAM","clue":"What animal was used, along with a young bull, when Aaron and his sons were installed as priests?","reference":"Exodus 29:1-3","url":"https://www.jw.org/en/library/bible/nwt/books/exodus/29/","insight":"The instructions called for a young bull and two unblemished rams, along with bread made without leaven. These were part of preparing Aaron and his sons to serve as priests. It wasn't just a change of clothing!"}]},{"rack":"SIMEON","size":7,"title":"Hope Fulfilled","scene":"23_isaiah.webp","spark":"SON","clue":"What the voice from the cloud called Jesus during the transfiguration","reference":"Matthew 17:5","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/17/","insight":"At the transfiguration, a voice from the cloud identified Jesus as God's beloved Son and told the disciples to listen to him.","words":[["SIMEON",2,1,"across"],["SIMON",0,3,"down"],["SOME",2,1,"down"],["MINE",0,6,"down"],["NOSE",0,1,"across"],["OMEN",4,0,"across"]],"bibleBoard":[{"word":"SIMEON","clue":"Man promised that he would see Jehovah's Christ before he died","reference":"Luke 2:25-32","url":"https://www.jw.org/en/library/bible/nwt/books/luke/2/","insight":"Holy spirit had revealed to Simeon that he wouldn't die before seeing Jehovah's Christ. When Mary and Joseph brought baby Jesus to the temple, Simeon took him in his arms and praised God. Imagine how meaningful that moment was!"},{"word":"SIMON","clue":"The name used for the fisherman Jesus also called Peter","reference":"Matthew 4:18-20","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/4/","insight":"Jesus saw Simon, who was called Peter, and his brother Andrew casting a fishing net. He invited them to follow him and become fishers of men. They left their nets and followed him at once!"}],"bonus":"SINE IONS EONS ONES MISO MEN ONE","extraSparks":[{"word":"NOISE","clue":"At Pentecost, what came from heaven sounding like a rushing, stiff breeze?","reference":"Acts 2:1-6","url":"https://www.jw.org/en/library/bible/nwt/books/acts/2/","insight":"Acts describes a noise like a rushing, stiff breeze—not an actual windstorm. Then the disciples spoke in different languages, and visitors from many places heard them in their own languages. What a remarkable beginning to that public witness!"}]},{"rack":"BABELS","size":7,"title":"A Confused City","scene":"01_genesis.webp","spark":"SEA","clue":"In John's vision of the heavenly throne, what looked glassy and clear as crystal?","reference":"Revelation 4:2-6","url":"https://www.jw.org/en/library/bible/nwt/books/revelation/4/","insight":"John saw something resembling a glassy sea, like crystal, before the throne in heaven. This was part of a striking vision, not the stormy water that Jesus calmed. What a different picture the same word can create!","words":[["BABEL",2,0,"across"],["ABEL",3,5,"down"],["SABLE",6,2,"across"],["BASE",2,0,"down"],["SALE",4,0,"across"],["BALES",2,2,"down"]],"bibleBoard":[{"word":"BABEL","clue":"Place whose name was connected with the confusion of language","reference":"Genesis 11:4-9","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/11/","insight":"The builders wanted a famous name for themselves and hoped to avoid being scattered. But Jehovah confused their language, so they could no longer understand one another and gradually stopped building the city. That's how the place came to be called Babel."},{"word":"ABEL","clue":"Shepherd who was Cain's brother","reference":"Genesis 4:2-5","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/4/","insight":"Abel cared for sheep while his brother Cain cultivated the ground. Both brought offerings to Jehovah, but Jehovah looked with favor on Abel and his gift, not on Cain and his. There was more to this account than their different jobs."}],"bonus":"BALE ABLE BABE LABS SLAB","extraSparks":[{"word":"SEAL","clue":"What Daniel was told to do to the book until the time of the end","reference":"Daniel 12:4, 8, 9","url":"https://www.jw.org/en/library/bible/nwt/books/daniel/12/","insight":"Daniel was told to keep the words secret and seal up the book until the time of the end. He admitted that he couldn't understand everything he'd heard, and the angel told him the words were to remain sealed. Even a faithful prophet didn't know every detail immediately."}]},{"rack":"GALILEE","size":7,"title":"Across Galilee","scene":"40_matthew.webp","spark":"EAGLE","clue":"Which bird does Jehovah describe nesting high on a cliff when speaking to Job?","reference":"Job 39:27-29","url":"https://www.jw.org/en/library/bible/nwt/books/job/39/","insight":"Jehovah asked Job whether an eagle soared and built its nest high on a cliff at Job's command. From there, the bird could search for food far below. The question helped put human understanding into perspective.","words":[["GALILEE",2,0,"across"],["ELI",2,6,"down"],["LEGAL",4,0,"across"],["GALE",2,0,"down"],["ALLEGE",0,2,"down"]],"bibleBoard":[{"word":"GALILEE","clue":"Region where Jesus taught in synagogues","reference":"Matthew 4:23-25","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/4/","insight":"Jesus traveled throughout Galilee, teaching in synagogues, preaching the good news of the Kingdom, and curing people with many kinds of illnesses. His ministry involved both teaching and real compassion for people who were suffering."},{"word":"ELI","clue":"Priest who asked Samuel not to hide the difficult message he had received","reference":"1 Samuel 3:15-18","url":"https://www.jw.org/en/library/bible/nwt/books/1-samuel/3/","insight":"Samuel was afraid to tell Eli the difficult message he'd received from Jehovah. Eli urged him not to hide a single word, so Samuel told him everything. Eli replied that Jehovah should do what was good in his eyes."}],"bonus":"LIEGE GILL GALL GEL LEG LIE","extraSparks":[{"word":"AGE","clue":"Psalm 92 says righteous people can keep thriving even in old what?","reference":"Psalm 92:12-15","url":"https://www.jw.org/en/library/bible/nwt/books/psalms/92/","insight":"Psalm 92 compares righteous people to flourishing trees. Even in old age, they can keep thriving and showing that Jehovah is upright. What an encouraging picture!"}]},{"rack":"RUTHEES","size":7,"title":"Faithful Women","scene":"08_ruth.webp","spark":"REST","clue":"What God began to do on the seventh day after finishing his creative work","reference":"Genesis 2:2, 3","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/2/","insight":"Genesis says God had completed the work he was doing by the seventh day and began to rest. He also blessed that day and declared it sacred. The account treats this rest as something especially important, not merely a break at the end of a busy week.","words":[["ESTHER",2,0,"across"],["RUTH",0,2,"across"],["THERE",0,4,"down"],["SHEET",4,1,"across"],["TREE",0,0,"down"]],"bibleBoard":[{"word":"ESTHER","clue":"Mordecai's orphaned cousin, who was also called Hadassah","reference":"Esther 2:7","url":"https://www.jw.org/en/library/bible/nwt/books/esther/2/","insight":"Esther's other name was Hadassah. After her parents died, her cousin Mordecai took her as his own daughter. He continued checking on her welfare even after she was taken into the king's household. What a caring detail in her story!"},{"word":"RUTH","clue":"Moabite widow who chose to stay with Naomi and worship her God","reference":"Ruth 1:14-17","url":"https://www.jw.org/en/library/bible/nwt/books/ruth/1/","insight":"Ruth had lost her husband, and Naomi urged her to return to her own people. But Ruth chose to stay. She committed herself not just to Naomi, but also to Naomi's people and Jehovah. Her loyalty involved a major change of life."}],"bonus":"SURE RUSE THUS RUSH RUST HURT SHUT","extraSparks":[{"word":"THREE","clue":"How many days and nights Jonah spent inside the huge fish","reference":"Jonah 1:17","url":"https://www.jw.org/en/library/bible/nwt/books/jonah/1/","insight":"After Jonah was thrown overboard, the raging sea became calm. Jehovah then sent a huge fish to swallow Jonah, and Jonah remained inside it for three days and three nights. The story didn't end when the sailors threw him into the sea!"}]},{"rack":"PAULST","size":7,"title":"A Witness to Nations","scene":"44_acts.webp","spark":"SALT","clue":"Jesus compared his disciples to what useful substance that can lose its strength?","reference":"Matthew 5:13","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/5/","insight":"Jesus called his disciples the salt of the earth, then asked what would happen if salt lost its strength. The comparison isn't just about having a label; it's about remaining genuinely useful.","words":[["PAUL",2,3,"across"],["SAUL",2,0,"down"],["PAST",2,3,"down"],["LAST",5,0,"across"],["LUST",2,6,"down"]],"bibleBoard":[{"word":"PAUL","clue":"At Acts 13:9, what other name is used for the missionary Saul?","reference":"Acts 13:4-9","url":"https://www.jw.org/en/library/bible/nwt/books/acts/13/","insight":"During the mission on Cyprus, Acts introduces the name Paul by saying that Saul was also called Paul. They're the same man! The account doesn't describe a brand-new apostle taking Saul's place."},{"word":"SAUL","clue":"Which name does Acts use for Paul before mentioning his other name during the Cyprus mission?","reference":"Acts 13:1-9","url":"https://www.jw.org/en/library/bible/nwt/books/acts/13/","insight":"At the start of the chapter, he is still called Saul as he and Barnabas begin their missionary trip. Later, verse 9 identifies him as also called Paul. The Bible doesn't say he was given that name on the trip."}],"bonus":"PLUS PALS PATS TAPS LAPS SLAT","extraSparks":[{"word":"SLAP","clue":"What action did Jesus mention when he taught his disciples not to retaliate?","reference":"Matthew 5:39","url":"https://www.jw.org/en/library/bible/nwt/books/matthew/5/","insight":"Jesus mentioned being slapped and turning the other cheek. Instead of striking back, his followers could choose a peaceful response. That can take real restraint."}]},{"rack":"PSALMS","size":7,"title":"Words of Praise","scene":"19_psalms.webp","spark":"LAMP","clue":"Psalm 119:105 compares God's word to what object that lights the way for your foot?","reference":"Psalm 119:105","url":"https://www.jw.org/en/library/bible/nwt/books/psalms/119/","insight":"A lamp helps you see where to put your next footstep. Psalm 119:105 compares God's word to a lamp for the foot and a light for the path. The picture suggests guidance for the next decision as well as the way ahead.","words":[["PSALMS",2,0,"across"],["PSALM",1,5,"down"],["MAPS",4,0,"across"],["SLAM",2,1,"down"],["PALMS",0,3,"down"]],"bibleBoard":[{"word":"PSALMS","clue":"Which Bible book begins by describing a happy person who loves Jehovah's law?","reference":"Psalm 1:1-3","url":"https://www.jw.org/en/library/bible/nwt/books/psalms/1/","insight":"The first psalm describes someone who enjoys Jehovah's law and reads it thoughtfully day and night. That person is compared to a tree planted by streams of water, producing fruit in its season. What a memorable opening to the book!"},{"word":"PSALM","clue":"What's an individual inspired song or prayer in the Bible book that includes chapter 23?","reference":"Psalm 23:1-4","url":"https://www.jw.org/en/library/bible/nwt/books/psalms/23/","insight":"Psalm 23 uses the picture of Jehovah as a caring shepherd. David describes being led to restful places and reassured even while walking through a dark valley. It's far more personal than just a song title."}],"bonus":"LAPS LASS MASS PASS AMPS ALMS","extraSparks":[{"word":"PALM","clue":"Tree used as a comparison for the flourishing righteous person","reference":"Psalm 92:12-14","url":"https://www.jw.org/en/library/bible/nwt/books/psalms/92/","insight":"Psalm 92 compares a righteous person to a flourishing palm tree. It goes on to say that such people can still thrive and remain vigorous even in old age. Isn't that a beautiful picture of lasting spiritual strength?"}]},{"rack":"JORDAN","size":7,"title":"Crossing the River","scene":"06_joshua.webp","spark":"ROD","clue":"What was Moses holding when Jehovah told him to throw it down as a sign?","reference":"Exodus 4:2-5","url":"https://www.jw.org/en/library/bible/nwt/books/exodus/4/","insight":"Moses was holding a rod. When he threw it down at Jehovah's direction, it became a serpent, and Moses fled! Jehovah then told him to take it by the tail, and it turned back into a rod. This sign would help others believe Jehovah had sent him.","words":[["JORDAN",2,0,"across"],["DAN",4,1,"across"],["ROAD",1,1,"down"],["ROAN",0,4,"down"],["DARN",0,2,"across"]],"bibleBoard":[{"word":"JORDAN","clue":"River Israel crossed on entering the Promised Land","reference":"Joshua 3:14-17","url":"https://www.jw.org/en/library/bible/nwt/books/joshua/3/","insight":"The Jordan was overflowing its banks during the harvest season. But when the priests carrying the ark stepped into the water, the flow upstream stopped. The priests stood on dry ground while all Israel crossed!"},{"word":"DAN","clue":"Which tribe captured Leshem and named the city after its forefather?","reference":"Joshua 19:40, 47, 48","url":"https://www.jw.org/en/library/bible/nwt/books/joshua/19/","insight":"Joshua tells us that the tribe of Dan found its territory too cramped. They captured Leshem, settled there, and renamed the city Dan after their forefather. That's a surprising link between a family name and a place on the map!"}],"bonus":"ADORN NOD DON AND RAN","extraSparks":[{"word":"JAR","clue":"What container did the widow tell Elisha she still had, with a little oil inside?","reference":"2 Kings 4:1-7","url":"https://www.jw.org/en/library/bible/nwt/books/2-kings/4/","insight":"The widow was afraid her sons would be taken because of a debt. All she had was a jar of oil. Elisha told her to borrow empty containers, and the oil kept pouring until they were filled! She could sell it to pay her debt and support her family."}]},{"rack":"LEVITES","size":7,"title":"Serving at the Tabernacle","scene":"04_numbers.webp","spark":"VEIL","clue":"What covering did Moses put over his face, a detail Paul later used as an illustration?","reference":"2 Corinthians 3:12-16","url":"https://www.jw.org/en/library/bible/nwt/books/2-corinthians/3/","insight":"Paul recalls Moses putting a veil over his face. Then he uses that image when discussing the former covenant and how understanding changes through Christ. A simple covering became part of a much bigger spiritual comparison.","words":[["LEVITES",3,0,"across"],["LEVI",0,3,"down"],["LIVES",0,1,"down"],["VILE",1,0,"across"],["STEEL",0,5,"down"]],"bibleBoard":[{"word":"LEVITES","clue":"Which tribe's men Jehovah chose for special service in place of Israel's firstborn sons?","reference":"Numbers 3:5-13","url":"https://www.jw.org/en/library/bible/nwt/books/numbers/3/","insight":"Jehovah chose the Levites in place of Israel's firstborn sons. They were assigned to assist Aaron and his sons with tabernacle duties. Not every Levite served as a priest, but the tribe had a special responsibility."},{"word":"LEVI","clue":"Which son did Leah name when she hoped Jacob would become more attached to her?","reference":"Genesis 29:34","url":"https://www.jw.org/en/library/bible/nwt/books/genesis/29/","insight":"After Leah gave birth to her third son, she named him Levi. She said that now her husband would become more attached to her because she'd borne him three sons. This family detail gives the name some human context."}],"bonus":"TILES SIEVE SLEET ELITE TIES SITE","extraSparks":[{"word":"EVIL","clue":"In Romans 12:21, what are Christians encouraged to keep conquering with good?","reference":"Romans 12:19-21","url":"https://www.jw.org/en/library/bible/nwt/books/romans/12/","insight":"Paul's advice goes beyond refusing revenge. Just before urging Christians to conquer evil with good, he speaks about feeding an enemy who's hungry and giving a thirsty enemy something to drink. The point is to respond with kindness instead of retaliation."}]}])

